import { DesignCanvas, DCSection, DCArtboard } from "@maude/canvas-lib";

export default function Welcome() {
  return (
    <DesignCanvas>
      <DCSection id="welcome" title="Welcome">
        <DCArtboard id="hello" label="Hello" kind="digital" width={1280} height={800} fixed>
          <div
            style={{
              width: "100%",
              height: "100%",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              background: "var(--bg-1)",
              color: "var(--fg-0)",
            }}
          >
            <h1 style={{ margin: 0 }}>Hello</h1>
          </div>
        </DCArtboard>
      </DCSection>
    </DesignCanvas>
  );
}
